// يحوّل تبويب Settings (key/value) إلى عنصر واحد
const S = {};
for (const it of $input.all()) {
  const r = it.json;
  if (r.key !== undefined && r.key !== null && String(r.key).trim() !== '') {
    S[String(r.key).trim()] = r.value;
  }
}
S.api_version = String(S.api_version || 'v23.0').trim();
S.phone_number_id = String(S.phone_number_id || '').trim();
return [{ json: S }];

// قرار الإرسال للحملات اللي إجا دورها + درع الجودة
const S = $('Settings').first().json;
const G = $('Gate').first().json;
const num = (v, d) => { const n = Number(v); return (v === '' || v === null || v === undefined || isNaN(n)) ? d : n; };
const now = $now.setZone('__TIMEZONE__');
const stamp = now.toFormat('yyyy-MM-dd HH:mm');
const stampS = now.toFormat('yyyy-MM-dd HH:mm:ss');
const want = new Set(G.send || []);
if (!want.size) return [];
const allRunning = $('Read Campaigns S').all().map(i => i.json)
  .filter(c => c.cid && String(c.status || '') === 'running' && String(c.archived || '') !== '1');
const camps = allRunning.filter(c => want.has(String(c.cid)));
if (!camps.length) return [];
const out = [];
const pause = (c, reason, status) => out.push({ json: { action: 'pause', cid: String(c.cid), name: String(c.name || ''), new_status: status || 'paused', reason, at: stamp } });
if (!S.phone_number_id) { allRunning.forEach(c => pause(c, 'ناقص رقم واتساب (phone_number_id) بالإعدادات العامة')); return out; }

// 1) جودة الرقم (على مستوى الرقم: بتوقف كل الحملات)
const guard = String(S.quality_guard || 'YELLOW').toUpperCase();
const q = $('Check Quality').first().json || {};
const sd = $getWorkflowStaticData('global');
if (guard !== 'OFF') {
  if (q.error) {
    sd.qErr = (sd.qErr || 0) + 1;
    if (sd.qErr < 3) return []; // عطل مؤقت عند ميتا: بنستنى الدورة الجاية
    allRunning.forEach(c => pause(c, 'ما قدرت أفحص جودة الرقم 3 مرات ورا بعض: ' + String(q.error.message || JSON.stringify(q.error)).slice(0, 200)));
    return out;
  }
  sd.qErr = 0;
  const quality = String(q.quality_rating || '').toUpperCase();
  const badQ = guard === 'RED' ? ['RED'] : ['YELLOW', 'RED'];
  if (badQ.includes(quality)) {
    allRunning.forEach(c => pause(c, 'جودة الرقم صارت ' + (quality === 'RED' ? 'حمرا' : 'صفرا') + '. وقفت الإرسال لحماية الرقم'));
    return out;
  }
}

// 2) الأرقام وقواعد كل الحملات
const contacts = $('Read Contacts').all().map(i => i.json).filter(c => String(c.phone || '').replace(/\D/g, ''));
const last9 = p => String(p || '').replace(/\D/g, '').slice(-9);
const D = c => String(c.delivery || '').trim();
const R = c => String(c.response || '').trim();
const optedOut = new Set();
for (const c of contacts) if (R(c) === 'opted_out') { optedOut.add(last9(c.phone)); if (c.wa_id) optedOut.add(last9(c.wa_id)); }
const lastSent = new Map(); // آخر رسالة حملة وصلت لكل شخص (من أي حملة)
for (const c of contacts) {
  const at = String(c.sent_at || ''); if (!at) continue;
  const k = last9(c.phone), p = lastSent.get(k);
  if (!p || at > p.at) lastSent.set(k, { at, cid: String(c.campaign || '') });
}
const today = now.toFormat('yyyy-MM-dd');
// نافذة الـ24 ساعة: اللي كتبلنا من أقل من 23 ساعة، ميتا ما بتمنع رسائلنا إله (حد رسائل التسويق ما بينطبق جوا النافذة)
const winCut = now.minus({ hours: 23 }).toFormat('yyyy-MM-dd HH:mm');
const lastIn = new Map();
for (const c of contacts) {
  const at = String(c.last_in_at || ''); if (!at) continue;
  for (const k of new Set([last9(c.phone), last9(c.wa_id)])) { if (k && (!lastIn.has(k) || at > lastIn.get(k))) lastIn.set(k, at); }
}
const winOpen = r => (lastIn.get(last9(r.phone)) || '') >= winCut || (!!r.wa_id && (lastIn.get(last9(r.wa_id)) || '') >= winCut);
const maxTries = Math.max(1, num(S.max_tries, 7));
const tries = r => num(r.tries, 0);
// حد الرقم اليومي مع التدرّج
const firstDay = contacts.map(c => String(c.sent_at || '').slice(0, 10)).filter(Boolean).sort()[0] || today;
const dayN = Math.max(0, Math.round(DateTime.fromISO(today).diff(DateTime.fromISO(firstDay), 'days').days));
const ramp = String(S.ramp || '').split(',').map(Number).filter(n => n > 0);
const dayLimit = Math.min(num(S.daily_limit, 200), ramp[dayN] || num(S.daily_limit, 200));
let remaining = dayLimit - contacts.filter(c => String(c.sent_at || '').startsWith(today)).length;
const gapCut = now.minus({ days: num(S.min_gap_days, 14) }).toFormat('yyyy-MM-dd HH:mm');
const maxRate = num(S.max_optout_rate, 0.05), optMin = num(S.optout_min, 50), maxErr = num(S.max_errors, 5);
const msgs = $('Read Messages').all().map(i => i.json);
const USED = ['sending', 'sent', 'delivered', 'read', 'failed', 'send_error'];

// 3) كل حملة: صحتها، عددها، ورسالتها
const queues = [];
for (const c of camps) {
  const cid = String(c.cid);
  const mine = contacts.filter(r => String(r.campaign || '') === cid);
  const stuck = now.minus({ hours: 6 }).toFormat('yyyy-MM-dd HH:mm');
  // ميتا منعت الرسالة (131049) أكثر من (max_tries) مرة وهو ما كتبلنا: بنوقف نحاول معه عشان ما نضر الرقم
  for (const r of mine) if (D(r) === 'retry_later' && String(r.error_code || '') === '131049' && tries(r) >= maxTries && !winOpen(r))
    out.push({ json: { action: 'giveup', phone: String(r.phone).trim(), campaign: cid, delivery: 'capped', updated_at: stamp,
      notes: `ميتا منعت الرسالة ${tries(r)} مرات (حد رسائل التسويق لهاد الشخص). إذا كتبلك، البرنامج بيبعتله لحاله` } });
  const gaveUp = r => D(r) === 'retry_later' && String(r.error_code || '') === '131049' && tries(r) >= maxTries && !winOpen(r);
  const left = mine.filter(r => (['', 'pending', 'retry_later', 'retry_alt', 'sending'].includes(D(r)) || (D(r) === 'capped' && winOpen(r)))
    && !gaveUp(r) && R(r) !== 'opted_out' && !optedOut.has(last9(r.phone))
    && !(D(r) === 'sending' && String(r.sent_at || '') < stuck)); // (sending) أقدم من 6 ساعات = علّق، ما بنعيده عشان ما يوصله مرتين
  if (mine.length && !left.length) { pause(c, 'انبعتت لكل الأرقام', 'done'); continue; }
  const reached = mine.filter(r => ['sent', 'delivered', 'read'].includes(D(r))).length;
  const oo = mine.filter(r => R(r) === 'opted_out').length;
  if (maxRate < 1 && reached >= optMin && oo / reached > maxRate) { pause(c, `نسبة (مش مهتم) عالية: ${oo} من ${reached}. راجع الرسالة قبل ما تكمل`); continue; }
  const errs = mine.filter(r => D(r) === 'send_error').length;
  if (maxErr > 0 && errs >= maxErr) { pause(c, `في ${errs} أخطاء إرسال. غالبًا مشكلة بالرسالة. افتح التتبّع وشوف الملاحظات`); continue; }
  const tcap = num(c.total_cap, 0);
  const used = mine.filter(r => USED.includes(D(r))).length;
  if (tcap > 0 && used >= tcap) { pause(c, `وصلت للعدد اللي حددته: ${tcap} رسالة`, 'done'); continue; }
  out.push({ json: { action: 'batch', cid, at: stampS } }); // دورها الجاي بعد (كل كم دقيقة) من هلقيت
  const versions = msgs.filter(m => String(m.campaign || '') === cid && String(m.active ?? '').toUpperCase() === 'TRUE'
    && String(m.status ?? '').toUpperCase() === 'APPROVED' && String(m.template_name ?? '').trim())
    .map(m => ({ name: String(m.template_name).trim(), has_name: String(m.has_name ?? '').toUpperCase() === 'TRUE' }));
  if (!versions.length) continue; // بنستنى موافقة واتساب على الرسالة
  const due = left.filter(r => {
    const d = D(r);
    if (d === 'sending') return false;
    if (d === 'retry_later' || d === 'capped') return winOpen(r) || String(r.retry_after || '') <= stamp; // اللي كتبلنا بنبعتله على طول
    return true;
  }).filter(r => { const ls = lastSent.get(last9(r.phone)); return !ls || ls.cid === cid || ls.at < gapCut; })
    .sort((a, b) => (winOpen(b) - winOpen(a)) || (num(a.priority, 9) - num(b.priority, 9))); // النافذة المفتوحة أول
  const sentTodayC = mine.filter(r => String(r.sent_at || '').startsWith(today)).length;
  const cap = num(c.daily_cap, 0) > 0 ? num(c.daily_cap, 0) - sentTodayC : Infinity;
  const tleft = tcap > 0 ? tcap - used : Infinity;
  const take = Math.min(Math.max(1, num(c.batch_size, num(S.batch_size, 20))), cap, tleft);
  if (take <= 0 || !due.length) continue;
  const usedV = {};
  for (const v of versions) usedV[v.name] = mine.filter(r => String(r.template ?? '') === v.name).length;
  queues.push({ c, cid, due, take, picked: 0, versions, used: usedV });
}

// 4) توزيع بالدور بين الحملات ضمن حد الرقم اليومي
const url = `https://graph.facebook.com/${S.api_version}/${S.phone_number_id}/messages`;
const lang = String(S.template_language || 'ar').trim();
const primary = String(S.primary_cc || '').replace(/\D/g, '');
const PS = primary === '970' || primary === '972'; // فلسطين: نفس الرقم بيشتغل بـ970 أو 972، فبنجرّب الثاني إذا الأول فشل
const altCc = primary === '970' ? '972' : '970';
const fallbackName = String(S.name_fallback ?? 'صديقنا').trim() || 'صديقنا';
const local = p => { let d = String(p).replace(/\D/g, ''); if (d.startsWith('00')) d = d.slice(2); if (d.startsWith('970') || d.startsWith('972')) d = d.slice(3); if (d.startsWith('0')) d = d.slice(1); return d; };
const intl = p => { let d = String(p).replace(/\D/g, ''); if (d.startsWith('00')) d = d.slice(2); if (d.startsWith('0') && primary) d = primary + d.slice(1); return d; }; // باقي الدول: الرقم الدولي كما هو
const chosen = new Set();
let progress = true;
while (remaining > 0 && progress) {
  progress = false;
  for (const qq of queues) {
    if (remaining <= 0) break;
    if (qq.picked >= qq.take) continue;
    while (qq.due.length) {
      const r = qq.due.shift();
      const k = last9(r.phone);
      if (chosen.has(k)) continue; // نفس الشخص ما بيوصله حملتين بنفس الدفعة
      chosen.add(k);
      const v = qq.versions.reduce((a, b) => qq.used[b.name] < qq.used[a.name] ? b : a);
      qq.used[v.name]++;
      const components = [];
      if (v.has_name) {
        const name = String(r.name || '').trim().split(/\s+/)[0] || fallbackName;
        components.push({ type: 'body', parameters: [{ type: 'text', text: name }] });
      }
      components.push(
        { type: 'button', sub_type: 'quick_reply', index: '0', parameters: [{ type: 'payload', payload: 'INTERESTED|' + qq.cid }] },
        { type: 'button', sub_type: 'quick_reply', index: '1', parameters: [{ type: 'payload', payload: 'STOP|' + qq.cid }] });
      const to = PS ? (D(r) === 'retry_alt' ? altCc : primary) + local(r.phone) : intl(r.phone);
      out.push({ json: { action: 'send', phone: String(r.phone).trim(), campaign: qq.cid, template: v.name, url, to, tries: tries(r) + 1,
        payload: { messaging_product: 'whatsapp', to, type: 'template', template: { name: v.name, language: { code: lang }, components } } } });
      remaining--; qq.picked++; progress = true;
      break;
    }
  }
}
return out;

// تحويل رد واتساب لسطر بالشيت (لكل رقم)
const src = $('Decide').item.json;
const r = $json || {};
const S = $('Settings').first().json;
const now = $now.setZone('__TIMEZONE__');
const stamp = now.toFormat('yyyy-MM-dd HH:mm');
const out = { phone: src.phone, campaign: src.campaign || '', template: src.template || '', sent_at: stamp, updated_at: stamp, wamid: '', wa_id: '', error_code: '', retry_after: '', notes: '', tries: String(src.tries || 1) };
if (r.messages && r.messages[0] && r.messages[0].id) {
  out.delivery = 'sent';
  out.wamid = r.messages[0].id;
  out.wa_id = (r.contacts && r.contacts[0] && r.contacts[0].wa_id) || src.to || '';
  out.notes = 'to:' + (src.to || '');
} else {
  const err = r.error || {};
  const code = Number(err.code);
  out.error_code = String(err.code || 'unknown');
  out.notes = String(err.message || err.error_user_msg || JSON.stringify(r)).slice(0, 250);
  if (code === 131026) {
    const primary = String(S.primary_cc || '').replace(/\D/g, '');
    const PS = primary === '970' || primary === '972'; // بس بفلسطين في مفتاح ثاني نجربه
    out.delivery = PS && String(src.to || '').startsWith(primary) ? 'retry_alt' : 'no_whatsapp';
  } else if (code === 131049) { // حد ميتا لكل شخص: بنستنى 24 ساعة على الأقل
    out.delivery = 'retry_later';
    out.retry_after = now.plus({ hours: Math.max(24, Number(S.cap_retry_hours) || 25) }).toFormat('yyyy-MM-dd HH:mm');
  } else if ([130472, 130429, 131056].includes(code)) {
    out.delivery = 'retry_later';
    const days = Number(S.retry_days) || 3;
    out.retry_after = now.plus({ days }).toFormat('yyyy-MM-dd');
  } else {
    out.delivery = 'send_error';
  }
}
return { json: out };

// فحص يومي: تذكير بتجديد السيرفر قبل ما ينتهي
const S = $('Settings').first().json;
const now = $now.setZone('__TIMEZONE__');
const sd = $getWorkflowStaticData('global');
const today = now.toFormat('yyyy-MM-dd');
if (now.hour < 10 || sd.lastDaily === today) return [];
const exp = DateTime.fromISO(String(S.server_expires || ''), { zone: '__TIMEZONE__' });
if (!exp.isValid) return [];
const left = Math.ceil(exp.diff(now.startOf('day'), 'days').days);
if (left > 5 || left < -1) return [];
sd.lastDaily = today;
const msg = left > 0 ? `السيرفر اللي عليه الحملات بينتهي بعد ${left} أيام (${exp.toFormat('yyyy-MM-dd')}). جدّده عند مزوّد السيرفر عشان الحملات والردود ما يوقفوا.`
  : 'السيرفر اللي عليه الحملات انتهى أو بينتهي اليوم. جدّده عند مزوّد السيرفر فورًا.';
return [{ json: { kind: 'server', key: 'server', title: '⚠️ جدّد السيرفر', body: msg, link: '', wa_text: msg.slice(0, 900) } }];

// متابعة مجانية: اللي كبس (بدي التفاصيل) وما كمّل، بنذكّره مرة وحدة بعد الوقت اللي حددته (جوا نافذة الـ24 ساعة)
const S = $('Settings').first().json;
const G = $('Gate').first().json;
const now = $now.setZone('__TIMEZONE__');
const num = (v, d) => { const n = Number(v); return (v === '' || v === null || v === undefined || isNaN(n)) ? d : n; };
if (!G.fu || !S.phone_number_id) return [];
const camps = {};
for (const it of $('Read Campaigns S').all()) { const c = it.json; if (c.cid) camps[String(c.cid)] = c; }
const url = `https://graph.facebook.com/${S.api_version}/${S.phone_number_id}/messages`;
const qlen = num(S.question_len, 25), maxN = Math.max(1, num(S.followup_batch, 20));
const out = [];
for (const it of $('Read Contacts').all()) {
  const c = it.json;
  if (String(c.response || '').trim() !== 'interested') continue;
  if (String(c.followup_at || '').trim() || String(c.followed_up || '').trim()) continue; // تابعناه قبل أو الفريق حكى معه
  if (String(c.delivery || '').trim() === 'skip' || !String(c.wa_id || '').trim()) continue;
  const cp = camps[String(c.campaign || '')] || {};
  if (String(cp.archived || '') === '1' || String(cp.followup_on || 'TRUE').toUpperCase() === 'FALSE') continue;
  if (String(cp.followup_skip_q || 'TRUE').toUpperCase() !== 'FALSE' && String(c.reply || '').trim().length > qlen) continue; // كتب سؤال: هاد بده رد من إنسان
  const tpl = String(cp.followup_reply || S.followup_reply || '').trim();
  if (!tpl) continue;
  const hs = num(cp.hour_start, num(S.send_hour_start, 10)), he = num(cp.hour_end, num(S.send_hour_end, 20));
  if (now.hour < hs || now.hour >= he) continue;
  const t = DateTime.fromFormat(String(c.updated_at || ''), 'yyyy-MM-dd HH:mm', { zone: '__TIMEZONE__' });
  if (!t.isValid) continue;
  const age = now.diff(t, 'minutes').minutes;
  if (age < num(cp.followup_after, 240) || age > 23.5 * 60) continue;
  const first = String(c.name || '').trim().split(/\s+/)[0];
  const body = first ? tpl.replace('{الاسم}', first) : tpl.replace(/\{الاسم\}[،,]?\s*/, '');
  out.push({ json: { phone: String(c.phone), campaign: String(c.campaign || ''), url, payload: { messaging_product: 'whatsapp', to: String(c.wa_id), type: 'text', text: { body } } } });
  if (out.length >= maxN) break;
}
return out;

// تسجيل إنه انبعتت المتابعة (حتى لو فشلت، ما بنعيدها)
const stamp = $now.setZone('__TIMEZONE__').toFormat('yyyy-MM-dd HH:mm');
return $input.all().map((it, i) => {
  const src = $('Follow Ups').all()[i].json;
  const ok = !!(it.json.messages && it.json.messages[0]);
  return { json: { phone: src.phone, campaign: src.campaign || '', followup_at: stamp + (ok ? '' : ' (ما وصلت)') } };
});

// تسجيل رسالة الحملة بصندوق المحادثات (عشان تبين المحادثة كاملة)
const stamp = $now.setZone('__TIMEZONE__').toFormat('yyyy-MM-dd HH:mm:ss');
const texts = {};
for (const it of $('Read Messages').all()) { const m = it.json; if (m.template_name) texts[String(m.template_name).trim()] = String(m.text || ''); }
const fb = String($('Settings').first().json.name_fallback ?? '').trim() || 'صديقنا';
const names = {};
for (const it of $('Read Contacts').all()) { const c = it.json; names[String(c.phone) + '|' + String(c.campaign || '')] = String(c.name || ''); }
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (r.delivery !== 'sent' || !r.wamid) continue;
  const wa = String(r.wa_id || '').replace(/\D/g, '');
  if (!wa) continue;
  const first = String(names[String(r.phone) + '|' + String(r.campaign || '')] || '').trim().split(/\s+/)[0] || fb;
  const body = (texts[String(r.template || '').trim()] || '(رسالة الحملة)').replace(/\{الاسم\}|\{\{1\}\}/g, first);
  out.push({ json: { wa_id: wa, name: '', dir: 'out', kind: 'template', text: body.slice(0, 4000), at: stamp,
    wamid: String(r.wamid), status: 'sent', seen: '1', campaign: String(r.campaign || '') } });
}
return out;

// تسجيل رسالة المتابعة بصندوق المحادثات
const stamp = $now.setZone('__TIMEZONE__').toFormat('yyyy-MM-dd HH:mm:ss');
const src = $('Follow Ups').all();
const out = [];
$input.all().forEach((it, i) => {
  const s = (src[i] || {}).json || {};
  const p = s.payload || {};
  if (!p.to) return;
  const ok = !!(it.json.messages && it.json.messages[0]);
  out.push({ json: { wa_id: String(p.to).replace(/\D/g, ''), name: '', dir: 'out', kind: 'followup',
    text: String((p.text || {}).body || '').slice(0, 4000), at: stamp,
    wamid: ok ? String(it.json.messages[0].id) : 'fail-' + Date.now() + '-' + i, status: ok ? 'sent' : 'failed', seen: '1', campaign: String(s.campaign || '') } });
});
return out;

// بوابة كل 5 دقايق: بنكمل بس إذا في حملة إجا دورها تبعت دفعة، أو صار وقت فحص المتابعات
const S = $('Settings').first().json;
const num = (v, d) => { const n = Number(v); return (v === '' || v === null || v === undefined || isNaN(n)) ? d : n; };
const now = $now.setZone('__TIMEZONE__');
const camps = $('Read Campaigns S').all().map(i => i.json).filter(c => c.cid && String(c.archived || '') !== '1');
const sd = $getWorkflowStaticData('global');
const days = c => { const d = String(c.days || '').split(',').map(Number).filter(x => x >= 1 && x <= 7); return d.length ? d : [1, 2, 3, 4, 5, 6, 7]; };
const open = c => {
  const hs = num(c.hour_start, num(S.send_hour_start, 10)), he = num(c.hour_end, num(S.send_hour_end, 20));
  if (now.hour < hs || now.hour >= he) return false;
  if (!days(c).includes(now.weekday)) return false;
  if (String(c.friday_pause || 'TRUE').toUpperCase() !== 'FALSE' && now.weekday === 5 && now.hour >= 11 && now.hour < 14) return false; // وقت صلاة الجمعة
  return true;
};
const due = c => {
  const t = DateTime.fromFormat(String(c.last_batch_at || ''), 'yyyy-MM-dd HH:mm:ss', { zone: '__TIMEZONE__' });
  return !t.isValid || now.diff(t, 'seconds').seconds >= Math.max(5, num(c.every_min, 20)) * 60 - 90;
};
const send = camps.filter(c => String(c.status || '') === 'running' && open(c) && due(c)).map(c => String(c.cid));
const fuOn = camps.some(c => String(c.followup_on || 'TRUE').toUpperCase() !== 'FALSE');
let manual = false; try { manual = $('Manual Test').isExecuted; } catch (e) {} // تشغيل يدوي: بنفحص المتابعات فورًا
const fu = fuOn && (manual || !sd.lastFu || Date.now() - sd.lastFu >= 9 * 60000); // المتابعات بنفحصها كل 10 دقايق تقريبًا
if (!send.length && !fu) return [];
if (fu) sd.lastFu = Date.now();
return [{ json: { ...S, send, fu } }];

// إشعار لما حملة توقف لحالها أو تخلص (على الأجهزة، وعلى واتساب إذا مشغّل)
return $input.all().map(it => {
  const p = it.json;
  const done = p.new_status === 'done';
  const nm = String(p.name || p.cid);
  return { json: { kind: 'camp', key: 'camp-' + p.cid,
    title: done ? `✅ خلصت حملة «${nm}»` : `⏸ وقفت حملة «${nm}» لحالها`,
    body: String(p.reason || '').slice(0, 250), link: 'camp=' + p.cid,
    wa_text: (done ? `خلصت حملة «${nm}»: ${p.reason || ''}` : `وقفت حملة «${nm}» لحالها: ${p.reason || ''}`).replace(/\s+/g, ' ').slice(0, 900) } };
});
